		fprintf(stderr,"%s:%d:color_esycc_to_rgb\n\tCAN NOT CONVERT\n", __FILE__,__LINE__);
		return;
	}

	w = image->comps[0].w;
	h = image->comps[0].h;

	sign1 = (int)image->comps[1].sgnd;
	sign2 = (int)image->comps[2].sgnd;

	max = w * h;

	for(i = 0; i < max; ++i)
	{

